// promptImportAgentHistory offers, at enable time, to import the repo's
// existing agent transcripts (past month) as read-only checkpoints. It works
// across every registered importer (Claude Code today). No-op when
// non-interactive, under --yes, or when nothing is found.
func promptImportAgentHistory(ctx context.Context, w io.Writer, opts EnableOptions) error {
	if opts.Yes || !interactive.CanPromptInteractively() {
		return nil
	}
	repoRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return nil //nolint:nilerr // not a git repo / nothing to import
	}
	now := time.Now()

	// Count importable turns across all registered importers.
	turnCount := 0
	withContent := make([]agentimport.Importer, 0)
